import liveIndexData from './live-companies/index.json';
import credData from './live-companies/cred.json';
import meeshoData from './live-companies/meesho.json';
import growwData from './live-companies/groww.json';
import inmobiData from './live-companies/inmobi.json';
import stripeData from './live-companies/stripe.json';
import datadogData from './live-companies/datadog.json';
import mongodbData from './live-companies/mongodb.json';
import elasticData from './live-companies/elastic.json';
import gitlabData from './live-companies/gitlab.json';
import rubrikData from './live-companies/rubrik.json';
import coinbaseData from './live-companies/coinbase.json';

import type { LiveMarketIndex, LiveCompanyData, LiveVerifiedRole } from '../../../scripts/market/sync-live-jobs';
import type { Company, Role } from '../../pages/demo/talentLensEngine';

export const LIVE_MARKET_INDEX = liveIndexData as LiveMarketIndex;

export const LIVE_COMPANIES_MAP: Record<string, LiveCompanyData> = {
  cred: credData as LiveCompanyData,
  meesho: meeshoData as LiveCompanyData,
  groww: growwData as LiveCompanyData,
  inmobi: inmobiData as LiveCompanyData,
  stripe: stripeData as LiveCompanyData,
  datadog: datadogData as LiveCompanyData,
  mongodb: mongodbData as LiveCompanyData,
  elastic: elasticData as LiveCompanyData,
  gitlab: gitlabData as LiveCompanyData,
  rubrik: rubrikData as LiveCompanyData,
  coinbase: coinbaseData as LiveCompanyData,
};

/**
 * Converts a raw live verified role into TalentLens Role format
 */
export function convertLiveRoleToTalentLensRole(liveRole: LiveVerifiedRole): Role {
  const workplaceLabel =
    liveRole.workplaceType === 'remote'
      ? 'Remote (India Eligible)'
      : liveRole.workplaceType === 'hybrid'
      ? 'Hybrid (India)'
      : 'On-Site';

  return {
    title: liveRole.title,
    level: liveRole.level,
    desc: liveRole.desc,
    competencies: liveRole.competencies,
    location: liveRole.location,
    employmentType: workplaceLabel,
    responsibilities: liveRole.responsibilities,
    requiredQualifications: liveRole.requiredQualifications,
    requiredSkills: liveRole.requiredSkills,
    toolsAndTech: liveRole.toolsAndTech,
    fullText: liveRole.fullText,
    source: liveRole.source,
    sourceUrl: liveRole.sourceUrl,
    lastVerified: liveRole.lastVerified,
    confidence: 'high',
    status: 'verified',
    isLiveVerified: true,
    contentHash: liveRole.contentHash,
  };
}

/**
 * Enriches an existing company with live verified roles from its ATS feed
 */
export function enrichCompanyWithLiveFeed(company: Company): Company {
  const liveData = LIVE_COMPANIES_MAP[company.id];
  if (!liveData || !liveData.roles || liveData.roles.length === 0) {
    return company;
  }

  const liveRoles = liveData.roles.map(convertLiveRoleToTalentLensRole);
  const existingNonLiveRoles = (company.roles || []).filter(
    (r) => !liveRoles.some((lr) => lr.title.toLowerCase() === r.title.toLowerCase())
  );

  return {
    ...company,
    openRoles: liveData.liveRoleCount,
    source: `Official ${liveData.ats.toUpperCase()} ATS Feed (Verified 3-Day Sync)`,
    sourceUrl: company.sourceUrl || liveData.website,
    lastVerified: liveData.lastSyncedAt,
    confidence: 'high',
    status: 'verified',
    dataStatus: 'live_verified',
    isLiveFeedActive: true,
    liveAts: liveData.ats,
    roles: [...liveRoles, ...existingNonLiveRoles],
  };
}

/**
 * Generates standalone Company objects for new flagship companies
 * that are verified via public ATS but were not in the legacy raw set.
 */
export function getStandaloneLiveCompanies(): Company[] {
  const newCompanyConfigs: Array<{
    id: string;
    logo: string;
    gradient: string;
    industry: string;
    tier: string;
    trend: string;
    avgPackage?: string;
  }> = [
    {
      id: 'datadog',
      logo: 'DD',
      gradient: 'from-purple-600 to-indigo-700',
      industry: 'Technology',
      tier: 'MNC',
      trend: 'up',
      avgPackage: '₹40-80 LPA',
    },
    {
      id: 'mongodb',
      logo: 'M',
      gradient: 'from-emerald-600 to-green-700',
      industry: 'Technology',
      tier: 'MNC',
      trend: 'up',
      avgPackage: '₹35-70 LPA',
    },
    {
      id: 'elastic',
      logo: 'E',
      gradient: 'from-cyan-600 to-blue-700',
      industry: 'Enterprise SaaS',
      tier: 'MNC',
      trend: 'stable',
      avgPackage: '₹32-65 LPA',
    },
    {
      id: 'gitlab',
      logo: 'GL',
      gradient: 'from-orange-500 to-amber-600',
      industry: 'Developer Tools',
      tier: 'MNC',
      trend: 'up',
      avgPackage: '₹38-75 LPA',
    },
    {
      id: 'rubrik',
      logo: 'R',
      gradient: 'from-blue-600 to-teal-600',
      industry: 'Technology',
      tier: 'MNC',
      trend: 'up',
      avgPackage: '₹42-85 LPA',
    },
    {
      id: 'coinbase',
      logo: 'CB',
      gradient: 'from-blue-600 to-indigo-800',
      industry: 'Fintech',
      tier: 'MNC',
      trend: 'stable',
      avgPackage: '₹45-90 LPA',
    },
  ];

  const standalone: Company[] = [];

  for (const cfg of newCompanyConfigs) {
    const liveData = LIVE_COMPANIES_MAP[cfg.id];
    if (!liveData) continue;

    const liveRoles = liveData.roles.map(convertLiveRoleToTalentLensRole);

    standalone.push({
      id: cfg.id,
      name: liveData.companyName,
      logo: cfg.logo,
      gradient: cfg.gradient,
      industry: cfg.industry,
      hq: liveData.headquarters,
      tier: cfg.tier,
      trend: cfg.trend,
      openRoles: liveData.liveRoleCount,
      avgPackage: cfg.avgPackage,
      source: `Official ${liveData.ats.toUpperCase()} ATS Feed (Verified 3-Day Sync)`,
      sourceUrl: liveData.website,
      lastVerified: liveData.lastSyncedAt,
      confidence: 'high',
      status: 'verified',
      dataStatus: 'live_verified',
      depth: 'deep',
      isLiveFeedActive: true,
      liveAts: liveData.ats,
      roles: liveRoles,
    });
  }

  return standalone;
}

/**
 * Returns summary stats for UI badges and honest provenance indicators
 */
export function getLiveFeedSummaryStats() {
  return {
    totalLiveRoles: LIVE_MARKET_INDEX.totalLiveRoles,
    companyCount: LIVE_MARKET_INDEX.companyCount,
    lastSyncTimestamp: LIVE_MARKET_INDEX.lastSyncTimestamp,
    cadence: LIVE_MARKET_INDEX.cadence,
  };
}
